//! Decoding tests for every supported format plus damaged/unsupported files.
//! Fixtures are generated by tools/make_fixtures.sh.

mod common;
use common::*;
use freemic::audio::decode::{decode_all, probe};

const RATE: f64 = 48000.0;

fn check_tones(name: &str, stereo_source: bool, lossy: bool) {
    let out = decode_all(&fixture(name), RATE as u32).unwrap_or_else(|e| panic!("{name}: {e}"));
    let secs = out.len() as f64 / 2.0 / RATE;
    assert!((0.97..1.08).contains(&secs), "{name}: duration {secs:.3}s");
    let start = (0.25 * RATE) as usize;
    let end = (0.75 * RATE) as usize;
    let l = &channel(&out, 0)[start..end];
    let r = &channel(&out, 1)[start..end];
    let fl = zero_crossing_freq(l, RATE);
    let fr = zero_crossing_freq(r, RATE);
    let expect_r = if stereo_source { 660.0 } else { 440.0 };
    assert!((fl - 440.0).abs() < 4.0, "{name}: left {fl:.1} Hz");
    assert!((fr - expect_r).abs() < 4.0, "{name}: right {fr:.1} Hz");
    let al = tone_amplitude(l, 440.0, RATE);
    assert!((al - 0.5).abs() < 0.06, "{name}: left amplitude {al:.3}");
    if stereo_source {
        // Channels must not be swapped or mixed.
        let leak = tone_amplitude(l, 660.0, RATE);
        assert!(leak < 0.01, "{name}: 660 Hz leaking into left ({leak:.4})");
    }
    if !lossy {
        // Residual after removing the fitted tone: resampling must be clean (> 60 dB SNR).
        let resid: f64 = {
            let w = 2.0 * std::f64::consts::PI * 440.0 / RATE;
            let (mut si, mut co) = (0.0, 0.0);
            for (i, s) in l.iter().enumerate() {
                si += *s as f64 * (w * i as f64).sin();
                co += *s as f64 * (w * i as f64).cos();
            }
            let n = l.len() as f64;
            let (a, b) = (2.0 * si / n, 2.0 * co / n);
            let mut e = 0.0;
            for (i, s) in l.iter().enumerate() {
                let fit = a * (w * i as f64).sin() + b * (w * i as f64).cos();
                e += (*s as f64 - fit).powi(2);
            }
            e / n
        };
        let snr = 10.0 * (0.125 / resid).log10();
        let min_snr = if name.contains("u8") { 35.0 } else { 60.0 };
        assert!(snr > min_snr, "{name}: SNR {snr:.1} dB");
    }
}

#[test]
fn wav_pcm16_44k_stereo() { check_tones("stereo_s16_44k.wav", true, false) }
#[test]
fn wav_pcm24_96k_stereo() { check_tones("stereo_s24_96k.wav", true, false) }
#[test]
fn wav_float32_48k_stereo() { check_tones("stereo_f32_48k.wav", true, false) }
#[test]
fn wav_u8_22k_mono() { check_tones("mono_u8_22k.wav", false, false) }
#[test]
fn wav_pcm16_8k_mono() { check_tones("mono_s16_8k.wav", false, false) }
#[test]
fn mp3_44k_stereo() { check_tones("stereo_44k.mp3", true, true) }
#[test]
fn mp3_22k_mono() { check_tones("mono_22k.mp3", false, true) }
#[test]
fn ogg_vorbis_48k_stereo() { check_tones("stereo_48k.ogg", true, true) }
#[test]
fn flac_24bit_44k_stereo() { check_tones("stereo_s24_44k.flac", true, false) }
#[test]
fn flac_16k_mono() { check_tones("mono_16k.flac", false, false) }
#[test]
fn m4a_aac_44k_stereo() { check_tones("stereo_aac_44k.m4a", true, true) }
#[test]
fn m4a_alac_48k_stereo() { check_tones("stereo_alac_48k.m4a", true, false) }

#[test]
fn surround_is_downmixed_without_clipping_samples() {
    let out = decode_all(&fixture("surround51_48k.wav"), 48000).unwrap();
    let l = channel(&out, 0);
    let f = zero_crossing_freq(&l[12000..36000], RATE);
    assert!((f - 440.0).abs() < 4.0);
    assert!(peak(&out) > 0.3);
}

#[test]
fn long_file_streams_full_length() {
    let out = decode_all(&fixture("long_20s.mp3"), 48000).unwrap();
    let secs = out.len() as f64 / 2.0 / RATE;
    assert!((19.95..20.1).contains(&secs), "duration {secs}");
}

#[test]
fn probe_reports_info() {
    let info = probe(&fixture("stereo_s24_96k.wav")).unwrap();
    assert_eq!(info.sample_rate, 96000);
    assert_eq!(info.channels, 2);
    assert!((info.duration_secs.unwrap() - 1.0).abs() < 0.01);
}

#[test]
fn bad_files_give_errors_not_panics() {
    for name in ["empty.wav", "not_audio.mp3", "truncated_header.wav", "does_not_exist.wav"] {
        let r = probe(&fixture(name));
        assert!(r.is_err(), "{name} should fail");
        let msg = r.unwrap_err();
        assert!(!msg.is_empty());
        println!("{name}: {msg}");
    }
}

#[test]
fn unsupported_codec_is_reported() {
    let r = probe(&fixture("opus_mono.ogg"));
    let msg = r.expect_err("Opus is not supported by the decoder");
    println!("opus: {msg}");
    assert!(msg.contains("not supported") || msg.contains("unsupported"), "{msg}");
}

#[test]
fn damaged_files_do_not_panic() {
    // These may decode partially or fail; either is fine as long as nothing panics.
    for name in ["corrupt.flac", "truncated.mp3"] {
        match decode_all(&fixture(name), 48000) {
            Ok(v) => println!("{name}: decoded {} frames", v.len() / 2),
            Err(e) => println!("{name}: error {e}"),
        }
    }
}
